package io.github.jaruizes.proposal.infrastructure.persistence.entity; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="agent_executions") @Getter @Setter @NoArgsConstructor public class AgentExecutionJpaEntity { @Id private UUID id; @Column(name="offer_id") private UUID offerId; private String phase; @Column(name="agent_key") private String agentKey; private String status; @Column(columnDefinition="text") private String objective; @Column(columnDefinition="text") private String output; private String model; @Column(name="input_tokens") private long inputTokens; @Column(name="output_tokens") private long outputTokens; @Column(name="provider_request_id") private String providerRequestId; @Column(name="started_at") private Instant startedAt; @Column(name="completed_at") private Instant completedAt; @Column(name="error_message",columnDefinition="text") private String errorMessage; }
